{"file_path": "/workspace/models.jac", "content": """"GHOST BOARD - Shared graph models.

Nodes, edges and enums shared by server.jac and client.jac.
"""

# -----------------------------------------------------------------------------
# Enums
# -----------------------------------------------------------------------------

enum ExecutiveStatus {
    IDLE = "IDLE",
    ANALYZING = "ANALYZING",
    DECIDING = "DECIDING",
    EXECUTING = "EXECUTING",
    OFFLINE = "OFFLINE"
}

enum Severity {
    LOW = "LOW",
    MEDIUM = "MEDIUM",
    HIGH = "HIGH",
    CRITICAL = "CRITICAL"
}

# -----------------------------------------------------------------------------
# Nodes
# -----------------------------------------------------------------------------

node Executive {
    has id: str = "",
        name: str = "",
        role: str = "",
        status: str = "IDLE",
        color: str = "white",
        is_thinking: bool = False,
        reasoning: str = "",
        confidence: float = 0.0;
}

node SystemMetrics {
    has system_load: float = 0.0,
        net_latency: int = 0,
        active_crises: int = 0,
        last_sync: str = "";
}

node Crisis {
    has id: str = "",
        message: str = "",
        severity: str = "MEDIUM",
        resolved: bool = False,
        created_at: str = "";
}

node IntelligenceReport {
    has executive_id: str = "",
        crisis_id: str = "",
        summary: str = "",
        confidence: float = 0.0,
        created_at: str = "";
}

# -----------------------------------------------------------------------------
# Edges
# -----------------------------------------------------------------------------

edge BoardMember {}

edge Monitors {}

edge Handles {}

edge Filed {}
"}

{"file_path": "/workspace/server.jac", "content": """"GHOST BOARD - Server API.

Graph initialization, public endpoints and orchestration walkers.
"""

import random;
import from datetime { datetime }
import from .models {
    ExecutiveStatus,
    Severity,
    Executive,
    SystemMetrics,
    Crisis,
    IntelligenceReport
}

# -----------------------------------------------------------------------------
# Helpers
# -----------------------------------------------------------------------------

def now_iso() -> str {
    return datetime.now().isoformat();
}

def find_executives() -> list[Executive] {
    result: list[Executive] = [];
    for n in [root -->] {
        if isinstance(n, Executive) {
            result.append(n);
        }
    }
    return result;
}

def find_metrics() -> SystemMetrics | None {
    for n in [root -->] {
        if isinstance(n, SystemMetrics) {
            return n;
        }
    }
    return None;
}

def classify_severity(msg: str) -> str {
    text = msg.lower();
    if "breach" in text or "outage" in text or "critical" in text {
        return Severity.CRITICAL.value;
    }
    if "attack" in text or "failure" in text or "urgent" in text {
        return Severity.HIGH.value;
    }
    if "delay" in text or "risk" in text {
        return Severity.MEDIUM.value;
    }
    return Severity.LOW.value;
}

# -----------------------------------------------------------------------------
# Graph Initialization
# -----------------------------------------------------------------------------

def initialize_graph() {
    if len(find_executives()) == 0 {
        roster = [
            ("ceo", "Atlas", "CHIEF EXECUTIVE", "white"),
            ("cto", "Cipher", "CHIEF TECHNOLOGY", "cyan"),
            ("cfo", "Ledger", "CHIEF FINANCIAL", "green"),
            ("cso", "Sentinel", "CHIEF SECURITY", "red"),
            ("coo", "Vector", "CHIEF OPERATIONS", "orange"),
            ("cmo", "Echo", "CHIEF MARKETING", "violet")
        ];
        for (eid, name, role, color) in roster {
            root ++> Executive(
                id=eid,
                name=name,
                role=role,
                status=ExecutiveStatus.IDLE.value,
                color=color,
                is_thinking=False,
                reasoning="Standing by for directives.",
                confidence=100.0
            );
        }
    }
    if find_metrics() is None {
        root ++> SystemMetrics(
            system_load=0.0,
            net_latency=0,
            active_crises=0,
            last_sync=now_iso()
        );
    }
}

# -----------------------------------------------------------------------------
# Walkers
# -----------------------------------------------------------------------------

walker SyncSystemStatus {
    can sync with entry {
        open_crises = 0;
        for n in [root -->] {
            if isinstance(n, Crisis) and not n.resolved {
                open_crises += 1;
            }
        }
        for n in [root -->] {
            if isinstance(n, SystemMetrics) {
                n.system_load = round(random.uniform(15.0, 45.0) + open_crises * 8.0, 1);
                n.net_latency = random.randint(8, 40) + open_crises * 5;
                n.active_crises = open_crises;
                n.last_sync = now_iso();
            }
        }
    }
}

walker OrchestrateCrisis {
    has crisis_msg: str = "",
        severity: str = "LOW",
        reports: list[dict] = [];

    can orchestrate with entry {
        severity = classify_severity(self.crisis_msg);
        self.severity = severity;
        crisis = Crisis(
            id=f"crisis-{random.randint(100000, 999999)}",
            message=self.crisis_msg,
            severity=severity,
            resolved=False,
            created_at=now_iso()
        );
        root ++> crisis;
        for ex in find_executives() {
            confidence = round(random.uniform(60.0, 99.0), 1);
            ex.status = ExecutiveStatus.EXECUTING.value;
            ex.is_thinking = False;
            ex.confidence = confidence;
            ex.reasoning = f"{ex.role}: {severity} response to '{self.crisis_msg}'.";
            report = IntelligenceReport(
                executive_id=ex.id,
                crisis_id=crisis.id,
                summary=ex.reasoning,
                confidence=confidence,
                created_at=now_iso()
            );
            crisis ++> report;
            self.reports.append(
                {"executive_id": ex.id, "summary": ex.reasoning, "confidence": confidence}
            );
        }
        report {"crisis_id": crisis.id, "severity": severity, "reports": self.reports};
    }
}

# -----------------------------------------------------------------------------
# Public API
# -----------------------------------------------------------------------------

def:pub get_executives() -> list[Executive] {
    initialize_graph();
    return find_executives();
}

def:pub get_system_metrics() -> SystemMetrics | None {
    initialize_graph();
    return find_metrics();
}

def:pub trigger_orchestration(crisis_msg: str) -> dict {
    msg = crisis_msg.strip();
    if not msg {
        return {"ok": False, "error": "Crisis message is required."};
    }
    initialize_graph();
    result = root spawn OrchestrateCrisis(crisis_msg=msg);
    root spawn SyncSystemStatus();
    return {"ok": True, "severity": result.severity, "reports": result.reports};
}
"}

